import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

batchnorm_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <algorithm>
__global__ void bn_reduce_kernel(
    const float* __restrict__ x,
    float* __restrict__ sum_out,
    float* __restrict__ sqsum_out,
    int N, int C, int H, int W)
{
    int c = blockIdx.x;
    int split = blockIdx.y;
    if (c >= C) return;
    long HW = (long)H * (long)W;
    long HW4 = HW / 4;
    long HW_rem_start = HW4 * 4;
    int n_per_split = (N + (int)gridDim.y - 1) / (int)gridDim.y;
    int n_start = split * n_per_split;
    int n_end = n_start + n_per_split;
    if (n_end > N) n_end = N;
    const int WARP_SIZE = 32;
    int lane = threadIdx.x & (WARP_SIZE - 1);
    int warp_id = threadIdx.x / WARP_SIZE;
    int num_warps = blockDim.x / WARP_SIZE;
    __shared__ float warp_sum[32];
    __shared__ float warp_sqsum[32];
    float sum = 0.0f;
    float sqsum = 0.0f;
    for (int n = n_start; n < n_end; n++) {
        const float4* x4 = reinterpret_cast<const float4*>(x + ((long)n * C + c) * HW);
        for (long i = threadIdx.x; i < HW4; i += blockDim.x) {
            float4 v = x4[i];
            sum += v.x + v.y + v.z + v.w;
            sqsum += v.x * v.x + v.y * v.y + v.z * v.z + v.w * v.w;
        }
        const float* xr = x + ((long)n * C + c) * HW;
        for (long i = HW_rem_start + threadIdx.x; i < HW; i += blockDim.x) {
            float v = xr[i];
            sum += v;
            sqsum += v * v;
        }
    }
    #pragma unroll
    for (int offset = WARP_SIZE / 2; offset > 0; offset >>= 1) {
        sum += __shfl_down_sync(0xffffffff, sum, offset);
        sqsum += __shfl_down_sync(0xffffffff, sqsum, offset);
    }
    if (lane == 0) {
        warp_sum[warp_id] = sum;
        warp_sqsum[warp_id] = sqsum;
    }
    __syncthreads();
    if (warp_id == 0) {
        float s = (lane < num_warps) ? warp_sum[lane] : 0.0f;
        float sq = (lane < num_warps) ? warp_sqsum[lane] : 0.0f;
        #pragma unroll
        for (int offset = WARP_SIZE / 2; offset > 0; offset >>= 1) {
            s += __shfl_down_sync(0xffffffff, s, offset);
            sq += __shfl_down_sync(0xffffffff, sq, offset);
        }
        if (lane == 0) {
            atomicAdd(&sum_out[c], s);
            atomicAdd(&sqsum_out[c], sq);
        }
    }
}
__global__ void bn_stats_kernel(
    const float* __restrict__ sum_in,
    const float* __restrict__ sqsum_in,
    float* __restrict__ mean_out,
    float* __restrict__ var_out,
    float* __restrict__ running_mean,
    float* __restrict__ running_var,
    int C, long count, float momentum)
{
    int c = blockIdx.x;
    if (c >= C) return;
    if (threadIdx.x != 0) return;
    float mean = sum_in[c] / (float)count;
    float var = sqsum_in[c] / (float)count - mean * mean;
    mean_out[c] = mean;
    var_out[c] = var;
    if (count > 1) {
        float unbiased_var = var * (float)count / (float)(count - 1);
        running_mean[c] = (1.0f - momentum) * running_mean[c] + momentum * mean;
        running_var[c] = (1.0f - momentum) * running_var[c] + momentum * unbiased_var;
    } else {
        running_mean[c] = (1.0f - momentum) * running_mean[c] + momentum * mean;
        running_var[c] = (1.0f - momentum) * running_var[c] + momentum * var;
    }
}
__global__ void bn_normalize_kernel(
    const float* __restrict__ x,
    float* __restrict__ y,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    const float* __restrict__ mean_in,
    const float* __restrict__ var_in,
    int N, int C, int H, int W,
    float eps)
{
    int c = blockIdx.x;
    int split = blockIdx.y;
    if (c >= C) return;
    long HW = (long)H * (long)W;
    long HW4 = HW / 4;
    long HW_rem_start = HW4 * 4;
    int n_per_split = (N + (int)gridDim.y - 1) / (int)gridDim.y;
    int n_start = split * n_per_split;
    int n_end = n_start + n_per_split;
    if (n_end > N) n_end = N;
    float mean = mean_in[c];
    float var = var_in[c];
    float inv_std = rsqrtf(var + eps);
    float w = weight[c];
    float b = bias[c];
    for (int n = n_start; n < n_end; n++) {
        const float4* x4 = reinterpret_cast<const float4*>(x + ((long)n * C + c) * HW);
        float4* y4 = reinterpret_cast<float4*>(y + ((long)n * C + c) * HW);
        for (long i = threadIdx.x; i < HW4; i += blockDim.x) {
            float4 v = x4[i];
            float4 r;
            r.x = (v.x - mean) * inv_std * w + b;
            r.y = (v.y - mean) * inv_std * w + b;
            r.z = (v.z - mean) * inv_std * w + b;
            r.w = (v.w - mean) * inv_std * w + b;
            y4[i] = r;
        }
        const float* xr = x + ((long)n * C + c) * HW;
        float* yr = y + ((long)n * C + c) * HW;
        for (long i = HW_rem_start + threadIdx.x; i < HW; i += blockDim.x) {
            float v = xr[i];
            yr[i] = (v - mean) * inv_std * w + b;
        }
    }
}
torch::Tensor batchnorm_forward_cuda(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    double eps,
    double momentum,
    bool training)
{
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 4, "x must be 4D (N, C, H, W)");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    x = x.contiguous();
    weight = weight.contiguous();
    bias = bias.contiguous();
    running_mean = running_mean.contiguous();
    running_var = running_var.contiguous();
    int N = x.size(0);
    int C = x.size(1);
    int H = x.size(2);
    int W = x.size(3);
    auto y = torch::empty_like(x);
    int threads = 256;
    int split = N;
    if (split > N) split = N;
    if (split < 1) split = 1;
    dim3 grid((unsigned int)C, (unsigned int)split);
    auto options = torch::TensorOptions().dtype(torch::kFloat32).device(x.device());
    torch::Tensor mean_buf, var_buf;
    if (training) {
        auto sum_buf = torch::zeros({C}, options);
        auto sqsum_buf = torch::zeros({C}, options);
        mean_buf = torch::empty({C}, options);
        var_buf = torch::empty({C}, options);
        bn_reduce_kernel<<<grid, threads>>>(
            x.data_ptr<float>(),
            sum_buf.data_ptr<float>(),
            sqsum_buf.data_ptr<float>(),
            N, C, H, W);
        long count = (long)N * (long)H * (long)W;
        int stat_threads = 32;
        int stat_blocks = C;
        bn_stats_kernel<<<stat_blocks, stat_threads>>>(
            sum_buf.data_ptr<float>(),
            sqsum_buf.data_ptr<float>(),
            mean_buf.data_ptr<float>(),
            var_buf.data_ptr<float>(),
            running_mean.data_ptr<float>(),
            running_var.data_ptr<float>(),
            C, count, (float)momentum);
    } else {
        mean_buf = running_mean;
        var_buf = running_var;
    }
    bn_normalize_kernel<<<grid, threads>>>(
        x.data_ptr<float>(),
        y.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        mean_buf.data_ptr<float>(),
        var_buf.data_ptr<float>(),
        N, C, H, W,
        (float)eps);
    return y;
}
"""

